/** 
 * Removes the given <tt>listener</tt> from the list of listeners currently registered for chat room member property change events.
 * @param listener the <tt>ChatRoomMemberPropertyChangeListener</tt> to remove.
 */
public void removeMemberPropertyChangeListener(final ChatRoomMemberPropertyChangeListener listener){
  synchronized (memberPropChangeListeners) {
    try {
      memberPropChangeListeners.remove(listener);
    } catch (NullPointerException | UnsupportedOperationException e) {
      // Log or ignore; the exception is benign
    }
  }
}
